            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;
                if (dp[mask] + nums[i] > target) continue;
                int nxt = mask | (1 << i);
                if (dp[nxt] < 0) dp[nxt] = (dp[mask] + nums[i]) % target;
            }
        }
        return dp[N - 1] == 0;
    }
};

