class Solution {
    public int minAbsDifference(int[] nums, int goal) {
        int n = nums.length, mid = n / 2;
        long[] A = subsetSums(nums, 0, mid);
        long[] B = subsetSums(nums, mid, n);
        java.util.Arrays.sort(B);
        long ans = Math.abs((long) goal);
        for (long a : A) {
            long need = goal - a;
            int i = lowerBound(B, need);
            if (i < B.length) ans = Math.min(ans, Math.abs(a + B[i] - goal));
            if (i > 0) ans = Math.min(ans, Math.abs(a + B[i - 1] - goal));
            if (ans == 0) return 0;
        }
        return (int) ans;
    }

    long[] subsetSums(int[] nums, int l, int r) {
        int m = r - l;
        long[] res = new long[1 << m];
        for (int mask = 0; mask < (1 << m); mask++) {
            long s = 0;
            for (int i = 0; i < m; i++)
                if ((mask & (1 << i)) != 0) s += nums[l + i];
            res[mask] = s;
        }
        return res;
    }

    int lowerBound(long[] b, long x) {
        int lo = 0, hi = b.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (b[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

