class Solution:
    def minAbsDifference(self, nums: list[int], goal: int) -> int:
        n = len(nums)
        mid = n // 2

        def subset_sums(arr: list[int]) -> list[int]:
            m = len(arr)
            res = [0] * (1 << m)
            for mask in range(1 << m):
                s = 0
                for i in range(m):
                    if mask >> i & 1:
                        s += arr[i]
                res[mask] = s
            return res

        A = subset_sums(nums[:mid])
        B = subset_sums(nums[mid:])
        B.sort()
        ans = abs(goal)
        for a in A:
            need = goal - a
            i = bisect.bisect_left(B, need)
            if i < len(B):
                ans = min(ans, abs(a + B[i] - goal))
            if i > 0:
                ans = min(ans, abs(a + B[i - 1] - goal))
            if ans == 0:
                return 0
        return ans

